interface IronEvent {
  readonly type: string;
  readonly target: { readonly id: number; readonly value: string; readonly type: string };
  stopPropagation(): void;
  preventDefault(): void;
}
interface IronPointerEvent extends IronEvent {
  readonly clientX: number;
  readonly clientY: number;
  readonly x: number;
  readonly y: number;
  readonly button: number;
  readonly buttons: number;
  readonly detail: number;
  readonly shiftKey: boolean;
  readonly ctrlKey: boolean;
  readonly altKey: boolean;
  readonly metaKey: boolean;
  readonly pointerId: number;
}
interface IronWheelEvent extends IronPointerEvent {
  readonly deltaX: number;
  readonly deltaY: number;
}
interface IronKeyboardEvent extends IronEvent {
  readonly key: string;
  readonly code: string;
  readonly repeat: boolean;
  readonly shiftKey: boolean;
  readonly ctrlKey: boolean;
  readonly altKey: boolean;
  readonly metaKey: boolean;
}
interface IronInputEvent extends IronEvent {
  readonly value: string;
}
interface IronFocusEvent extends IronEvent {}
interface IronScrollEvent extends IronEvent {
  readonly scrollLeft: number;
  readonly scrollTop: number;
  readonly scrollWidth: number;
  readonly scrollHeight: number;
  readonly clientWidth: number;
  readonly clientHeight: number;
}
interface IronElement {
  focus(): void;
  blur(): void;
  scrollTo(x: number, y: number): void;
}
type ReactNode = ReactElementLike | string | number | boolean | null | undefined | ReactNode[];
interface ReactElementLike {
  readonly __element: never;
}
interface Ref<T> {
  current: T;
}

interface IronProps {
  key?: string | number;
  className?: string;
  id?: string;
  style?: IronStyle;
  children?: ReactNode;
  ref?: Ref<IronElement | null>;
  tabIndex?: number;
  disabled?: boolean;
  checked?: boolean;
  placeholder?: string;
  value?: string;
  dir?: string;
  src?: string;
  title?: string;
  rows?: number;
  cols?: number;
  type?: string;
  onClick?: (e: IronPointerEvent) => void;
  onDoubleClick?: (e: IronPointerEvent) => void;
  onPointerDown?: (e: IronPointerEvent) => void;
  onPointerUp?: (e: IronPointerEvent) => void;
  onPointerMove?: (e: IronPointerEvent) => void;
  onPointerEnter?: (e: IronPointerEvent) => void;
  onPointerLeave?: (e: IronPointerEvent) => void;
  onMouseDown?: (e: IronPointerEvent) => void;
  onMouseUp?: (e: IronPointerEvent) => void;
  onWheel?: (e: IronWheelEvent) => void;
  onKeyDown?: (e: IronKeyboardEvent) => void;
  onKeyUp?: (e: IronKeyboardEvent) => void;
  onChange?: (e: IronInputEvent) => void;
  onInput?: (e: IronInputEvent) => void;
  onFocus?: (e: IronFocusEvent) => void;
  onBlur?: (e: IronFocusEvent) => void;
  onScroll?: (e: IronScrollEvent) => void;
  [key: `data-${string}`]: string | number | boolean | undefined;
}

declare namespace JSX {
  type Element = ReactElementLike;
  interface ElementChildrenAttribute {
    children: {};
  }
  interface IntrinsicAttributes {
    key?: string | number;
  }
  interface IntrinsicElements {
    box: IronProps;
    text: IronProps;
    span: IronProps;
    input: IronProps;
    textarea: IronProps;
    image: IronProps;
    list: IronProps;
    dialog: IronProps;
    svg: IronProps;
    [tag: string]: IronProps;
  }
}

declare namespace React {
  type ReactNode = globalThis.ReactNode;
  type CSSProperties = IronStyle;
}

// The names of `react`, `@iron/react` and `@iron/engine`'s UI side are globals: a game needs no import.
// `iron-build types` also declares the three modules as re-exports of these (see `types_dts.rs`).
declare function useState<T>(init: T | (() => T)): [T, (v: T | ((prev: T) => T)) => void];
declare function useEffect(f: () => void | (() => void), deps?: readonly unknown[]): void;
declare function useLayoutEffect(f: () => void | (() => void), deps?: readonly unknown[]): void;
declare function useRef<T>(init: T): Ref<T>;
declare function useRef<T>(init: null): Ref<T | null>;
declare function useMemo<T>(f: () => T, deps: readonly unknown[]): T;
declare function useCallback<F extends (...args: any[]) => any>(f: F, deps: readonly unknown[]): F;
declare function useReducer<S, A>(reducer: (s: S, a: A) => S, init: S): [S, (a: A) => void];
declare function createContext<T>(def: T): { Provider: (props: { value: T; children?: ReactNode }) => ReactElementLike };
declare function useContext<T>(c: { Provider: unknown } & { __t?: T }): T;
declare function memo<P>(c: (props: P) => ReactElementLike | null): (props: P) => ReactElementLike | null;
declare function forwardRef<P, T>(f: (props: P, ref: Ref<T>) => ReactElementLike | null): (props: P & { ref?: Ref<T> }) => ReactElementLike | null;

// The compiler lowers console.* calls itself (no DOM lib needed).
declare const console: {
  log(...args: unknown[]): void;
  info(...args: unknown[]): void;
  debug(...args: unknown[]): void;
  warn(...args: unknown[]): void;
  error(...args: unknown[]): void;
};

declare function createRoot(target?: WorldPanel | Window | number): { render(node: ReactNode): void; unmount(): void };
declare function Text(props: IronProps): ReactElementLike;
declare function Span(props: IronProps): ReactElementLike;
declare function Input(props: IronProps): ReactElementLike;
declare function TextArea(props: IronProps): ReactElementLike;
declare function Image(props: IronProps): ReactElementLike;
declare function List(props: IronProps): ReactElementLike;
declare function Dialog(props: IronProps): ReactElementLike;

type FullScreenMode = "ExclusiveFullScreen" | "FullScreenWindow" | "MaximizedWindow" | "Windowed";
